1; % OctaLink standalone script: GNU Octave 7+; all integration executes here.
% Generated from the validated detached model; no Python required.

function y = ol_scalar(x)
  if numel(x) ~= 1 || ~isreal(x) || ~isfinite(x)
    error('OctaLink: expected one finite real scalar; use Demux for vectors');
  endif
  y = double(x);
endfunction
function y = ol_power(a,b)
  if abs(b) > 1024, error('OctaLink: exponent magnitude exceeds 1024'); endif
  y = ol_scalar(a^b);
endfunction
function y = ol_mod(a,b)
  if b == 0, error('OctaLink: division by zero'); endif
  y = mod(a,b);
endfunction
function ol_finite(x)
  if ~isreal(x) || any(~isfinite(x(:)))
    error('OctaLink: non-finite or complex signal/state; reduce dt or check model');
  endif
endfunction

function [v,dx,z] = ol_evaluate(t,x,z,update,hits,left_step)
v = cell(14,1); dx = zeros(2,1);
if t >= 0, v{1}=1; else v{1}=0; endif
ol_finite(v{1});
v{5} = x(1:1);
ol_finite(v{5});
v{10} = x(2:2);
ol_finite(v{10});
v{6} = 1*ol_scalar(v{5});
ol_finite(v{6});
v{7} = 0.01*ol_scalar(v{5});
ol_finite(v{7});
v{11} = 0.10000000000000001*ol_scalar(v{10});
ol_finite(v{11});
v{12} = 0.01*ol_scalar(v{10});
ol_finite(v{12});
v{13} = [reshape(v{10},1,[]),reshape(v{5},1,[])];
ol_finite(v{13});
v{2} = 0+ol_scalar(v{1})-ol_scalar(v{6});
ol_finite(v{2});
v{8} = 0+ol_scalar(v{7})-ol_scalar(v{11});
ol_finite(v{8});
v{14} = reshape(v{13},1,[]);
ol_finite(v{14});
v{3} = 0+ol_scalar(v{2})-ol_scalar(v{12});
ol_finite(v{3});
v{9} = 100*ol_scalar(v{8});
ol_finite(v{9});
v{4} = 2*ol_scalar(v{3});
ol_finite(v{4});
dx(1:1) = ol_scalar(v{4});
dx(2:2) = ol_scalar(v{9});
ol_finite(dx);
endfunction
